import { AppConfig, saveSettings, isWebOSTV, clearStorage } from './app.js';
import { renderSidebar, setActivePage } from './ui/components/sidebarMenu.js';

/* ──────────────────────────────────────────────────────────────────────────
   1. ROUTER STATE & CONFIGURATION
   ────────────────────────────────────────────────────────────────────────── */

/**
 * @typedef {Object} Route
 * @property {string} name - Route identifier
 * @property {string} title - Page title
 * @property {Function} render - Render function
 * @property {Function} [onEnter] - Called when entering route
 * @property {Function} [onLeave] - Called when leaving route
 */

/** @type {Map<string, Route>} */
const routes = new Map();

/** @type {Object} */
const routerState = {
    currentRoute: null,
    previousRoute: null,
    history: [],
    isNavigating: false,
    maxHistory: 10
};

/** @type {Object} */
const navigationState = {
    focusedIndex: 0,
    focusableElements: [],
    isRemoteMode: false,
    lastInputType: null
};

/* ──────────────────────────────────────────────────────────────────────────
   GLOBAL INPUT & NAVIGATION GUARD
   ────────────────────────────────────────────────────────────────────────── */

let remoteControlInitialized = false;
let globalKeyHandlersInitialized = false;
let sidebarNavigationInitialized = false;
let lastRemoteActionAt = 0;
let lastRemoteKey = '';
let lastNavigationAt = 0;

const REMOTE_REPEAT_GUARD_MS = 180;
const NAVIGATION_GUARD_MS = 250;

const REMOTE_KEYS = new Set([
    'ArrowUp',
    'ArrowDown',
    'ArrowLeft',
    'ArrowRight',
    'Enter',
    'Backspace',
    'Escape'
]);

const shouldIgnoreRemoteInput = (key) => {
    const now = performance.now();

    if (key === lastRemoteKey && (now - lastRemoteActionAt < REMOTE_REPEAT_GUARD_MS)) {
        return true;
    }

    lastRemoteKey = key;
    lastRemoteActionAt = now;
    return false;
};

const shouldIgnoreNavigation = () => {
    const now = performance.now();

    if (now - lastNavigationAt < NAVIGATION_GUARD_MS) {
        return true;
    }

    lastNavigationAt = now;
    return false;
};

/* ──────────────────────────────────────────────────────────────────────────
   2. DOM CACHE (Null-safe)
   ────────────────────────────────────────────────────────────────────────── */

const elements = {
    sidebar: document.getElementById('main-sidebar'),
    content: document.getElementById('main-content'),
    appShell: document.getElementById('app-shell'),
    toastContainer: document.getElementById('toast-container'),
    modalOverlay: document.getElementById('modal-overlay'),
    playerOverlay: document.getElementById('player-overlay'),
    quickSettings: document.getElementById('quick-settings'),
    searchOverlay: document.getElementById('search-overlay')
};



/* ──────────────────────────────────────────────────────────────────────────
   3. ROUTE DEFINITIONS
   ────────────────────────────────────────────────────────────────────────── */

/**
 * Register all application routes
 */
const registerRoutes = () => {
    routes.set('home', {
        name: 'home',
        title: 'Ana Sayfa'
    });

    routes.set('live', {
        name: 'live',
        title: 'Canlı TV'
    });

    routes.set('movies', {
        name: 'movies',
        title: 'Filmler'
    });

    routes.set('series', {
        name: 'series',
        title: 'Diziler'
    });

    routes.set('favorites', {
        name: 'favorites',
        title: 'Favoriler'
    });

    routes.set('settings', {
        name: 'settings',
        title: 'Ayarlar'
    });

    routes.set('player', {
        name: 'player',
        title: 'Oynatıcı',
        isOverlay: true
    });

    routes.set('search', {
        name: 'search',
        title: 'Arama',
        isOverlay: true
    });
    
    console.info('[Router] Routes registered:', routes.size);
};

/* ──────────────────────────────────────────────────────────────────────────
   4. SIDEBAR NAVIGATION
   ────────────────────────────────────────────────────────────────────────── */

/**
 * Update active navigation item (Calls modular Sidebar component)
 * @param {string} routeName - Current route name
 */
const updateActiveNav = (routeName) => {
    setActivePage(routeName);
};

/* ──────────────────────────────────────────────────────────────────────────
   5. ROUTER CORE FUNCTIONS
   ────────────────────────────────────────────────────────────────────────── */

/**
 * Navigate to a route
 * @param {string} routeName - Route identifier
 * @param {Object} [params] - Route parameters
 * @returns {Promise<boolean>} Success status
 */
const routeTo = async (routeName, params = {}) => {
    if (routerState.isNavigating) {
        console.warn('[Router] Navigation in progress, ignoring request');
        return false;
    }

    if (shouldIgnoreNavigation()) {
        console.debug('[Router] Navigation ignored by time guard:', routeName);
        return false;
    }

    const route = routes.get(routeName);
    if (!route) {
        console.error('[Router] Route not found:', routeName);
        showToast('Sayfa bulunamadı', 'error');
        return false;
    }
    
    routerState.isNavigating = true;
    routerState.previousRoute = routerState.currentRoute;
    
    try {
        // Call onLeave for current route
        if (routerState.currentRoute) {
            const prevRoute = routes.get(routerState.currentRoute);
            if (prevRoute?.onLeave) {
                await prevRoute.onLeave();
            }
        }
        
        // Update history
        if (routerState.currentRoute && !route.isOverlay) {
            routerState.history.push(routerState.currentRoute);
            if (routerState.history.length > routerState.maxHistory) {
                routerState.history.shift();
            }
        }
        
        // ------------------------------------------------------------------
        // Dynamic Import Implementation
        // ------------------------------------------------------------------
        let screenModule;

        switch (routeName) {
            case 'home': {
                screenModule = await import('./ui/screens/homeScreen.js');
                await screenModule.renderHomeScreen(params);
                break;
            }
            case 'live':
            case 'movies':
            case 'series': {
                screenModule = await import('./ui/screens/browseScreen.js');
                await screenModule.renderBrowseScreen({ mode: routeName, ...params });
                break;
            }
            case 'settings': {
                screenModule = await import('./ui/screens/settingsScreen.js');
                await screenModule.renderSettingsScreen(params);
                break;
            }
            case 'favorites': {
                screenModule = await import('./ui/screens/favoritesScreen.js');
                await screenModule.renderFavoritesScreen(params);
                break;
            }
            case 'player': {
                console.log('[Router] Opening player with params:', params);

                screenModule = await import('./ui/screens/playerScreen.js');

                const playerData = params?.data || params;

                await screenModule.renderPlayerScreen(playerData.channel || playerData, {
                    channelList: playerData.channelList || [],
                    currentIndex: Number.isFinite(playerData.currentIndex)
                        ? playerData.currentIndex
                        : 0
                });

                break;
            }
            case 'search': {
                screenModule = await import('./ui/screens/browseScreen.js');
                await screenModule.renderBrowseScreen({ mode: 'search', ...params });
                break;
            }
            default:
                showToast('Sayfa bulunamadı', 'error');
                return false;
        }
        
        // Update state
        routerState.currentRoute = routeName;
        AppConfig.settings.lastPage = routeName;
        saveSettings();
        
        // Update UI
        updateActiveNav(routeName);

        // Attach generic content action handlers for current screen buttons
        attachContentActionHandlers();
        
        // Call onEnter for new route
        if (route.onEnter) {
            await route.onEnter(params);
        }
        
        // Dispatch custom event
        window.dispatchEvent(new CustomEvent('fonex:route:change', {
            detail: { route: routeName, params }
        }));
        
        console.info('[Router] Navigation complete:', routeName);
        return true;
        
    } catch (error) {
        console.error('[Router] Navigation failed detail:', {
            routeName,
            message: error && error.message,
            name: error && error.name,
            stack: error && error.stack
        });

        showToast(`Sayfa yüklenemedi: ${routeName}`, 'error');
        return false;
        
    } finally {
        routerState.isNavigating = false;
    }
};

/**
 * Go back to previous route
 * @returns {Promise<boolean>}
 */
const goBack = async () => {
    if (routerState.history.length === 0) {
        console.warn('[Router] No history to go back');
        return false;
    }
    
    const previousRoute = routerState.history.pop();
    return await routeTo(previousRoute);
};

/**
 * Go to home route
 * @returns {Promise<boolean>}
 */
const goHome = async () => {
    return await routeTo('home');
};

/* ──────────────────────────────────────────────────────────────────────────
   6. VIEW CLEANUP & TRANSITIONS
   ────────────────────────────────────────────────────────────────────────── */

// Bu bölüm artık dinamik importlar (Section 5) tarafından yönetiliyor.
// Legacy rendererlar kaldırıldı.


/* ──────────────────────────────────────────────────────────────────────────
   7. ROUTE HOOKS (RESERVED)
   ────────────────────────────────────────────────────────────────────────── */

// onEnter / onLeave kancaları gelecek özellikler için rezerve edildi.


/* ──────────────────────────────────────────────────────────────────────────
   8. REMOTE CONTROL / D-PAD HANDLING (webOS)
   ────────────────────────────────────────────────────────────────────────── */

/**
 * Initialize remote control handling
 */
const initRemoteControl = () => {
    if (remoteControlInitialized) {
        console.debug('[Router] Remote control already initialized');
        return;
    }

    if (!isWebOSTV()) {
        console.info('[Router] Remote control disabled (not webOS)');
        return;
    }

    remoteControlInitialized = true;
    document.addEventListener('keydown', handleRemoteKey, { passive: false });
    console.info('[Router] Remote control enabled');
};

/**
 * Handle remote key presses
 * @param {KeyboardEvent} e - Key event
 */
const handleRemoteKey = (e) => {
    if (elements.playerOverlay?.classList.contains('active')) {
        return;
    }

    if (!REMOTE_KEYS.has(e.key)) return;

    const keyMap = {
        'ArrowUp': 'up',
        'ArrowDown': 'down',
        'ArrowLeft': 'left',
        'ArrowRight': 'right',
        'Enter': 'select',
        'Backspace': 'back',
        'Escape': 'back'
    };

    const action = keyMap[e.key];
    if (!action) return;

    if (shouldIgnoreRemoteInput(e.key)) {
        e.preventDefault();
        e.stopPropagation();
        return;
    }

    e.preventDefault();
    e.stopPropagation();

    console.debug('[Router] Remote key:', action);

    switch (action) {
        case 'up':
            moveFocus('up');
            break;
        case 'down':
            moveFocus('down');
            break;
        case 'left':
            moveFocus('left');
            break;
        case 'right':
            moveFocus('right');
            break;
        case 'select':
            selectFocused();
            break;
        case 'back':
            goBack();
            break;
    }
};

/**
 * Move focus in direction
 * @param {string} direction - up, down, left, right
 */
const moveFocus = (direction) => {
    const focusable = document.querySelectorAll('.focusable, .nav-item, button, [tabindex="0"]');
    const current = document.activeElement;
    const currentIndex = Array.from(focusable).indexOf(current);
    
    if (currentIndex === -1) return;
    
    let nextIndex = currentIndex;
    
    switch (direction) {
        case 'down':
            nextIndex = Math.min(currentIndex + 1, focusable.length - 1);
            break;
        case 'up':
            nextIndex = Math.max(currentIndex - 1, 0);
            break;
        case 'right':
            nextIndex = Math.min(currentIndex + 3, focusable.length - 1);
            break;
        case 'left':
            nextIndex = Math.max(currentIndex - 3, 0);
            break;
    }
    
    if (nextIndex !== currentIndex) {
        focusable[nextIndex]?.focus();
    }
};

/**
 * Select currently focused element
 */
const selectFocused = () => {
    const focused = document.activeElement;
    if (focused) {
        focused.click();
        focused.classList.add('focus-burst');
        setTimeout(() => focused.classList.remove('focus-burst'), 300);
    }
};

/* ──────────────────────────────────────────────────────────────────────────
   9. EVENT DELEGATION
   ────────────────────────────────────────────────────────────────────────── */


/**
 * Attach delegated action handler to content area buttons
 * (non-breaking enhancement: supports existing data-action attributes)
 */
const attachContentActionHandlers = () => {
    if (!elements.content) return;

    // Prevent duplicate bindings across re-renders
    if (elements.content.dataset.actionsBound === 'true') return;

    elements.content.addEventListener('click', (e) => {
        const target = e.target.closest('[data-action]');
        if (!target) return;

        const action = target.dataset.action;
        if (!action) return;

        switch (action) {
            case 'watch-live':
                routeTo('live');
                break;
            case 'browse-movies':
                routeTo('movies');
                break;
            case 'refresh-channels':
                routeTo('live');
                showToast('Kanal listesi yenilendi', 'success');
                break;
            case 'filter-movies':
                showToast('Filtre paneli yakında eklenecek', 'info');
                break;
            case 'search-movies':
                routeTo('search');
                break;
            default:
                break;
        }
    });

    elements.content.dataset.actionsBound = 'true';
};

/* ──────────────────────────────────────────────────────────────────────────
   10. HELPER FUNCTIONS
   ────────────────────────────────────────────────────────────────────────── */


/* ──────────────────────────────────────────────────────────────────────────
   11. TOAST NOTIFICATIONS
   ────────────────────────────────────────────────────────────────────────── */

let lastToastTime = 0;
let lastToastMessage = '';

/**
 * Show toast notification
 * @param {string} message - Toast message
 * @param {string} type - success, error, info, warning
 */
const showToast = (message, type = 'info') => {
    if (!elements.toastContainer) return;
    
    // Spam protection: Don't show same message within 2 seconds
    const now = Date.now();
    if (message === lastToastMessage && (now - lastToastTime) < 2000) {
        return;
    }
    
    lastToastTime = now;
    lastToastMessage = message;
    
    const toast = document.createElement('div');
    toast.className = `glass-toast toast-${type}`;
    toast.innerHTML = `
        <span>${message}</span>
    `;
    
    elements.toastContainer.appendChild(toast);
    
    // Animate in
    requestAnimationFrame(() => {
        toast.classList.add('visible');
    });
    
    // Remove after delay
    setTimeout(() => {
        toast.classList.remove('visible');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
};

/* ──────────────────────────────────────────────────────────────────────────
   12. ROUTER INITIALIZATION
   ────────────────────────────────────────────────────────────────────────── */

/**
 * Initialize router and all subsystems
 * @returns {Promise<void>}
 */
const initRouter = async () => {
    console.log('%c[Router] Initializing...', 'color:#8B5CF6;font-weight:bold;');
    
    try {
        // 1. Register all routes
        registerRoutes();
        
        // 2. Build sidebar navigation (Using Modular Component)
        renderSidebar(routerState.currentRoute);

        // Handle sidebar navigation events
        if (!sidebarNavigationInitialized) {
            sidebarNavigationInitialized = true;

            document.addEventListener('sovereign:navigate', (e) => {
                const route = e.detail?.page;
                if (route) routeTo(route);
            });
        }
        
        // 3. Initialize remote control (webOS)
        initRemoteControl();
        
        // 4. Setup global keyboard handlers
        setupGlobalKeyHandlers();
        
        console.info('[Router] Initialization complete');
        
    } catch (error) {
        console.error('[Router] Initialization failed:', error);
        throw error;
    }
};

/**
 * Setup global keyboard handlers
 */
const setupGlobalKeyHandlers = () => {
    if (globalKeyHandlersInitialized) {
        console.debug('[Router] Global key handlers already initialized');
        return;
    }

    globalKeyHandlersInitialized = true;

    document.addEventListener('keydown', (e) => {
        // Search shortcut (Ctrl+F or F3)
        if ((e.ctrlKey && e.key === 'f') || e.key === 'F3') {
            e.preventDefault();
            routeTo('search');
            return;
        }
        
        // Settings shortcut (S)
        if (e.key === 's' && !e.ctrlKey && !e.altKey) {
            e.preventDefault();
            routeTo('settings');
            return;
        }

        // Sidebar quick focus/expand shortcut
        if (e.key === 'm' && !e.ctrlKey && !e.altKey) {
            e.preventDefault();
            
            const firstNav = elements.sidebar?.querySelector('.nav-item');
            if (firstNav) {
                elements.sidebar?.classList.add('is-expanded');
                elements.sidebar?.setAttribute('aria-expanded', 'true');
                firstNav.focus();
            }
        }
    });
};

/* ──────────────────────────────────────────────────────────────────────────
   13. EXPORTS
   ────────────────────────────────────────────────────────────────────────── */

export {
    initRouter,
    routeTo,
    goBack,
    goHome,
    showToast,
    routes,
    routerState
};

export default {
    initRouter,
    routeTo,
    goBack,
    goHome,
    showToast,
    routes,
    routerState
};

